INSERT INTO reports (tracking_id, summary, description, status, risk_level, risk_level_source, department_id, reporter_id, reporter_type, building_id, building_name_snapshot, is_indoor, floor, room, location_description, space_type, space_code, space_name, unit_type, scene_id, pin_x, pin_y, pin_z, pin_label, submitted_at, created_at, updated_at, resolved_at)
SELECT 'DM-' || lpad(v.seq::text, 6, '0'), v.title, v.descr, v.status, v.risk, 'AI', d.id,
       (SELECT id FROM users WHERE provider = 'GOOGLE' AND provider_id = 'dummy-reporter'), 'REAL_NAME',
       b.id, b.name, v.indoor, v.floor, v.room, v.location, v.space_type, v.space_code, v.space_name,
       v.unit_type, v.scene_id, v.px, v.py, v.pz, v.pin_label, v.at, v.at, COALESCE(v.resolved, v.at), v.resolved
FROM v JOIN buildings b ON b.name = v.building JOIN departments d ON d.code = v.dept;
COMMIT;
